-- Tenant defaults used by the Android POS for printer, scale and cash drawer I/O.
SET @table_name = 'hardware_settings';

SET @column_name='print_mode'; SET @ddl=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=@table_name AND COLUMN_NAME=@column_name)=0,'ALTER TABLE `hardware_settings` ADD COLUMN `print_mode` VARCHAR(20) NOT NULL DEFAULT ''escpos'' AFTER `weighing_machine_port`','SELECT 1'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @column_name='paper_width'; SET @ddl=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=@table_name AND COLUMN_NAME=@column_name)=0,'ALTER TABLE `hardware_settings` ADD COLUMN `paper_width` SMALLINT NOT NULL DEFAULT 80 AFTER `print_mode`','SELECT 1'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @column_name='weighing_baud_rate'; SET @ddl=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=@table_name AND COLUMN_NAME=@column_name)=0,'ALTER TABLE `hardware_settings` ADD COLUMN `weighing_baud_rate` INT NOT NULL DEFAULT 9600 AFTER `paper_width`','SELECT 1'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @column_name='weighing_data_bits'; SET @ddl=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=@table_name AND COLUMN_NAME=@column_name)=0,'ALTER TABLE `hardware_settings` ADD COLUMN `weighing_data_bits` TINYINT NOT NULL DEFAULT 8 AFTER `weighing_baud_rate`','SELECT 1'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @column_name='weighing_stop_bits'; SET @ddl=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=@table_name AND COLUMN_NAME=@column_name)=0,'ALTER TABLE `hardware_settings` ADD COLUMN `weighing_stop_bits` TINYINT NOT NULL DEFAULT 1 AFTER `weighing_data_bits`','SELECT 1'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @column_name='weighing_parity'; SET @ddl=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=@table_name AND COLUMN_NAME=@column_name)=0,'ALTER TABLE `hardware_settings` ADD COLUMN `weighing_parity` VARCHAR(10) NOT NULL DEFAULT ''none'' AFTER `weighing_stop_bits`','SELECT 1'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @column_name='cash_drawer_pin'; SET @ddl=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=@table_name AND COLUMN_NAME=@column_name)=0,'ALTER TABLE `hardware_settings` ADD COLUMN `cash_drawer_pin` TINYINT NOT NULL DEFAULT 0 AFTER `cash_drawer`','SELECT 1'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
SET @column_name='open_drawer_after_sale'; SET @ddl=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=@table_name AND COLUMN_NAME=@column_name)=0,'ALTER TABLE `hardware_settings` ADD COLUMN `open_drawer_after_sale` TINYINT NOT NULL DEFAULT 1 AFTER `cash_drawer_pin`','SELECT 1'); PREPARE s FROM @ddl; EXECUTE s; DEALLOCATE PREPARE s;
